ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-dvol-20261003';INPUT=ROOT/'data/btc-dvol-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fore=read(RUN/'forecast-summary.json');audit=read(INPUT/'independent-audit.json')
 assert len(s)==v['accounts']==60 and rep['all_bytes_equal'] and rep['matched_files']==103 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[];loss=[]
