 evidence={'build':'1003d1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fore,'data_audit':audit,'scope':'BTC-only development, option-implied variance for spot/cash risk sizing; current historical DVOL not first-release vintages; no accepted strategy'}
