  files.extend((p,'input/dvol/'+str(p.relative_to(INPUT))) for p in sorted(INPUT.rglob('*')) if p.is_file());files.append((ROOT/'data/btc-venue-20261003/masks.json','input/btc-no-trade-mask.json'))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
