 files=['btc-dvol-research.html','btc-web-research.html','downloads/btc-dvol-evidence.zip','downloads/btc-dvol-evidence.json','downloads/btc-dvol-summary.csv','EXPERIMENT_BTC_DVOL_20261003.md','BTC_WEB_RESEARCH_20261002.md'];out=ROOT/'runs/btc-dvol-report-20261003';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files),'zip_bytes':(DOWN/'btc-dvol-evidence.zip').stat().st_size}))
